for i in range(6):
    msg = await history.get(i)
    print(f"--- Message {i}, kind={msg.get('kind')}, step={msg.get('step')} ---")
    if msg.get('kind') == 'assistant':
        content = await history.read(i, cursor=0)
        print(content.get('text', '')[:1000])
    elif msg.get('kind') == 'user':
        print(msg.get('text', '')[:1000])
    else:
        print(str(msg)[:1000])
    print()
